const express  = require('express');
const helmet   = require('helmet');
const cors     = require('cors');
const morgan   = require('morgan');
const rateLimit = require('express-rate-limit');
const { requireAuth } = require('./auth.middleware');

// ── Startup validation ────────────────────────────────────────────────────────
for (const key of ['JWT_SECRET']) {
  if (!process.env[key]) {
    console.error(`FATAL: Missing required env var: ${key}`);
    process.exit(1);
  }
}

const app = express();

// ── Security middleware ───────────────────────────────────────────────────────
app.disable('x-powered-by');
app.use(helmet());
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS ?? '').split(','),
  credentials: true,
}));
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));
app.use(morgan('combined'));
app.use(express.json({ limit: '10kb' })); // body size cap

// ── Routes ────────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  // Minimal response — no internal info
  res.json({ status: 'ok' });
});

app.get('/users/me', requireAuth, (req, res) => {
  const user = getUserById(req.user.sub);
  if (!user) return res.status(404).json({ error: 'Not found' });
  const { id, name } = user;          // return only needed fields
  res.json({ id, name });
});

// ── Global error handler (must be last) ──────────────────────────────────────
app.use((err, req, res, _next) => {
  console.error({ err, path: req.path });
  const status = err.status ?? 500;
  res.status(status).json({
    error: status < 500 ? err.message : 'An unexpected error occurred',
  });
});

// ── Process-level safety net ─────────────────────────────────────────────────
process.on('unhandledRejection', (reason) => console.error('Unhandled rejection:', reason));

app.listen(3000, () => console.log('Server running on port 3000'));
module.exports = app;
```

