  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    ...
  ]);
});
```

**Recommended fix — add a JWT middleware guard:**
```js
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Missing authorization token' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Apply to protected routes
app.get('/users', requireAuth, (req, res) => { ... });
```

---

### 🔴 Finding 2 — Secrets in Version-Controlled Files (OWASP A02: Cryptographic Failures / Secrets Exposure)

`.env.test` is sitting in the project root with no `.gitignore`. Even with "canary" labels, this file establishes a habit of committing secrets and will eventually catch real credentials.

**Recommended fix:**

Create `.gitignore`:
```
# .gitignore
.env
.env.*
*.env
node_modules/
```

Load secrets safely at runtime:
```js
// Use dotenv only for local dev — never commit the file
require('dotenv').config();

const dbUrl = process.env.DATABASE_URL;
if (!dbUrl) {
  throw new Error('DATABASE_URL is required but not set');
}
```

For production, use a secrets manager (AWS Secrets Manager, HashiCorp Vault, etc.) rather than `.env` files at all.

