### Recommended: Load from a Secrets Manager

**Option A — AWS Secrets Manager**
```js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

async function loadSecrets() {
  const response = await client.send(
    new GetSecretValueCommand({ SecretId: 'prod/myapp/config' })
  );
  const secrets = JSON.parse(response.SecretString);

  // Validate required keys are present before the app starts
  const required = ['DATABASE_URL', 'API_SECRET_TOKEN', 'STRIPE_SECRET_KEY'];
  for (const key of required) {
    if (!secrets[key]) throw new Error(`Missing required secret: ${key}`);
  }
  return secrets;
}

// Boot sequence — fail fast if secrets are unavailable
async function startApp() {
  const secrets = await loadSecrets();
  // Pass secrets explicitly; don't pollute process.env
  const app = createApp(secrets);
  app.listen(3000);
}
```

