```js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR,  // only non-secret config in env
  token:    process.env.VAULT_TOKEN, // short-lived, injected by Vault Agent
});

async function loadSecrets() {
  const { data } = await vault.read('secret/data/myapp/prod');
