function validateSecrets(secrets) {
  const required = {
    DATABASE_URL:       /^postgres:\/\/.+/,
    API_SECRET_TOKEN:   /^.{32,}$/,   // minimum 32 chars
    STRIPE_SECRET_KEY:  /^sk_(live|test)_.+/,
